"""Manually authored permit-dossier proposals; no canonical mutations."""
import json, pathlib, re, html
D=pathlib.Path(__file__).resolve().parent
S=json.loads((D/'source.json').read_text())
C=json.loads((D/'companion/source.json').read_text())
answers={}

def text(xml):
    return re.sub(r'\s+',' ',html.unescape(re.sub('<[^>]*>',' ',xml or ''))).strip()

def paragraphs(*parts):return '\n'.join('<p>'+p+'</p>' for p in parts)

def item(number,body,reason,notes,benefits,classification='material_reduction',removed=None):
    source=next(x for x in S+C if x['number']==number)
    a={k:source[k] for k in ('code_id','source_id','source_sha256','number')}
    a.update(status='retained_unchanged' if body is None else 'rewrite_draft',proposed_xml=body,
             reason=reason,review_notes=notes,benefit_review=benefits)
    if removed:
        a.update(change_type='normative_reduction',reform_policy_id='editorial_direction_2026_10_19',removed_provisions=removed)
    a['substantive_impact']={
        'version':1,'classification':classification,'assessment':reason,
        'scope_limitations':"Examen limité au présent dossier de permis et aux renvois capturés ; aucune économie budgétaire, baisse de taxe ou réduction automatique du délai total n'est chiffrée. Les procédures autonomes non modifiées conservent leur champ.",
        'new_burdens_review':"Aucune nouvelle déclaration ou attestation de remplacement. Le contenu de sécurité, les conditions des avantages et les compétences conservés ne sont pas des suppressions. Les transmissions des pièces sont décrites dans le circuit commun, sans nouveau dépôt du demandeur.",
        'effects':[]}
    answers[number]=a
    return a

def effect(number,kind,mid,description,before,after,sq,pq,conditions=None,new=None):
    a=answers[number];s=next(x for x in S+C if x['number']==number)
    assert sq in text(s['source_xml']),(number,sq)
    assert pq in text(a['proposed_xml']),(number,pq)
    a['substantive_impact']['effects'].append(dict(kind=kind,measure_id=mid,description=description,
        before=before,after=after,unit='legal_duty',source_quote=sq,proposed_quote=pq,
        affected_population="Pétitionnaires, autorités instructrices et services consultés dans le champ de cet article.",
        conditions_and_transition=conditions or "Demandes nouvelles et demandes en cours dans le champ temporel expressément fixé ; aucune reprise des délais ni remise en cause automatique des décisions et droits antérieurs.",
        replacement_or_new_burdens=new or "Aucune pièce de remplacement. Les documents substantiels et autorisations expressément conservés gardent leurs conditions ; leur transmission commune ne crée pas un contrôle supplémentaire."))

def repeal(number,body,reason,notes,benefits,scope,classification='material_reduction'):
    a=item(number,body,reason,notes,benefits,classification)
    a.update(change_type='full_repeal',repeal_policy_id='editorial_direction_2026_10_19',repeal_scope=scope)
    return a

